def styled_chart(fig, height_px=320, title=None):
    fig.update_layout(
        margin=dict(l=44, r=20, t=44, b=44), height=height_px,
        paper_bgcolor="white", plot_bgcolor="#F7FAFC",
        title_font=dict(size=13, color="#1B4F72", family="Arial Black"),
        font=dict(color="#2C3E50", size=11, family="Arial"),
        legend=dict(font=dict(size=10, color="#2C3E50"), bgcolor="rgba(255,255,255,0.9)", bordercolor="#DDE4EC", borderwidth=1),
    )
    if title is not None:
        fig.update_layout(title=title)
    fig.update_xaxes(**AXIS_STYLE)
    fig.update_yaxes(**AXIS_STYLE)
    return fig

