# ==================================================
# 📦 DATA LOADING
# ==================================================
@st.cache_data(show_spinner="Reading budget workbook...")
def load_budget(file_bytes):
    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)
    ws = wb["Budget-full Year"]

    def v(coord):
        val = ws[coord].value
        return val if isinstance(val, (int, float)) else 0

    # Monthly income (recomputed from leaf rows 4-8, not the corrupted row-9 formula)
    monthly_income = [sum(v(f"{c}{r}") for r in range(4, 9)) for c in MCOLS]
    monthly_expense = [v(f"{c}61") for c in MCOLS]

    income_sources = {
        "Incubation Services": v("O4"),
        "Consultancy services": v("O5"),
        "Trainings & workshops": v("O6"),
        "Boot Camp services": v("O7"),
        "Grants": v("O8"),
    }

    categories = {
        "Salaries & Human Resources": v("O12"),
        "Operations (Trainings & Workshops)": v("O35"),
        "Marketing & Communication": v("O39"),
        "Rent": v("O27"),
        "Utilities": v("O29") + v("O30") + v("O32"),
        "Transport & Travel": v("O57") + v("O58"),
        "Equipment & Technology": v("O28") + v("O33") + v("O34"),
        "Administration": v("O44") + sum(v(f"{c}46") for c in MCOLS) + v("O47") + v("O48") + v("O59") + v("O60"),
        "Taxes": v("O50") + v("O51") + v("O53") + v("O54"),
        "Other (Statutory & Debt Service)": v("O52") + v("O55") + v("O56") + v("O49"),
    }

    total_revenue = sum(monthly_income)
    total_expenses_reported = v("O61")  # authoritative annual total per source workbook
    total_expenses_monthly_sum = sum(monthly_expense)
    net_profit = total_revenue - total_expenses_reported

    # Rebuilt clean cash flow (uses actual monthly figures month-by-month, as budgeted;
    # note: monthly Total Expenses cells do not sum exactly to the source workbook's
    # annual 'Total Expenses' cell due to partial-range formulas within the source file —
    # see Assumptions & Data page)
    opening, closing, net_cf = [], [], []
    bal = 0.0
    for inc, exp_m in zip(monthly_income, monthly_expense):
        opening.append(bal)
        n = inc - exp_m
        net_cf.append(n)
        bal = bal + n
        closing.append(bal)

    return {
        "monthly_income": monthly_income,
        "monthly_expense": monthly_expense,
        "income_sources": income_sources,
        "categories": categories,
        "total_revenue": total_revenue,
        "total_expenses": total_expenses_reported,
        "total_expenses_monthly_sum": total_expenses_monthly_sum,
        "net_profit": net_profit,
        "opening": opening,
        "closing": closing,
        "net_cf": net_cf,
    }

