def build_forecast(rev_g, exp_g):
    revs = [rev]; exps = [exp]
    for _ in range(4):
        revs.append(revs[-1] * (1 + rev_g))
        exps.append(exps[-1] * (1 + exp_g))
    profit = [r - e for r, e in zip(revs, exps)]
    return revs, exps, profit

