    st.markdown("""
    <div style="background:white; border-left:5px solid #D35400; border-radius:10px; padding:16px 18px; box-shadow:0 2px 10px rgba(27,79,114,0.08); font-size:13px; color:#2C3E50; line-height:1.7;">
    <b>1. Human Resources double-count:</b> the 'Staff' subtotal sums a range that already contains the 'Consultants' subtotal, so 'Human Resources' overstates true consultant cost.<br>
    <b>2. Total Expenses formula gap:</b> the source 'Total Expenses' formula (= HR + Infrastructure + Marketing + Other) omits the Trainings &amp; Workshops line.<br>
    <b>3. Blank annual-total cell:</b> the Stationery line's annual-total cell is blank, so it drops out of any total that relies on that cell.<br>
    <b>4. Inconsistent Balance formula:</b> the source 'Total Income'/'Balance' rows mix simple monthly sums (Jan–May) with carried-forward cumulative logic (Jun–Dec) — this app rebuilds a clean, consistent cash-flow model instead.<br>
    <b>5. Monthly vs. annual expense totals don't reconcile:</b> several underlying annual-total cells (e.g. within Human Resources and Infrastructure) use partial-month ranges rather than the full Jan–Dec range, so summing the 12 monthly 'Total Expenses' cells (RWF {monthly_sum}) does not equal the source workbook's own annual 'Total Expenses' cell (RWF {annual_total}) used throughout this dashboard as the authoritative figure. Monthly charts still use the actual budgeted monthly figures.
    </div>""".format(monthly_sum=f"{data['total_expenses_monthly_sum']:,.0f}", annual_total=f"{data['total_expenses']:,.0f}"), unsafe_allow_html=True)

    section_header("Raw Monthly Data", "#7D3C98")
